_ORDER = ('ar', 'el', 'es', 'fr', 'hi', 'ru', 'tl', 'zh')


def _(s, l=None):
    l = l or lang()
    if l == 'en' or l not in _ORDER:
        return s
    t = _T.get(s)
    return t[_ORDER.index(l)] if t else s


def rtl():
    return lang() == 'ar'
